  grid_spacing_m: f32,
  max_future_substeps: u32,
  separation_enabled: u32,
  state_stride_vec4s: u32,
  thermo_stride_vec4s: u32,
  mechanics_stride_vec4s: u32,
  max_bin_scan_radius: u32,
  thermal_phase_evolution_enabled: u32,
